sys_script_include.script:
var XeroIntegrationUtils = Class.create();
XeroIntegrationUtils.prototype = {
    initialize: function() {},

        syncCompanyFromContact: function(contact) {

        var result = {
            company_sys_id: '',
            is_new_company: false,
            not_found: false
        };

        // Without ContactID and Name there is nothing safe to search for.
        // (A query with an empty/invalid value can return ALL rows)
        if (!contact || (!contact.ContactID && !contact.Name)) {
            result.not_found = true;
            return result;
        }

        var address = this.getAddress(contact);
        var phones = this.getPhones(contact);

        var company;

        // Search the account by Xero Contact ID (only when Xero sent one)
        if (contact.ContactID) {

            company = new GlideRecord('customer_account');
            company.addQuery('x_snc_spm_xero_i_0_xero_contact_id', contact.ContactID);
            company.query();

            if (company.next()) {
                this.updateCompany(company, contact, address, phones);
                company.update();
                result.company_sys_id = company.getUniqueValue();
                return result;
            }
        }

        // Without a name we cannot search by name
        if (!contact.Name) {
            result.not_found = true;
            return result;
        }

        // Search the account by name
        company = new GlideRecord('customer_account');
        company.addQuery('name', contact.Name);
        company.query();

        if (company.next()) {
            this.updateCompany(company, contact, address, phones);
            company.update();
            result.company_sys_id = company.getUniqueValue();
            return result;
        }

        // No match: the account is NOT created (data governance).
        // The flow leaves the project without account and warns the PM.
        result.not_found = true;
        return result;
    },

    getAddress: function(contact) {

        var result = {
            street: '',
            city: '',
            state: '',
            postalCode: '',
            country: ''
        };

        if (!contact.Addresses) {
            return result;
        }

        for (var i = 0; i < contact.Addresses.length; i++) {

            var address = contact.Addresses[i];

            if (address.AddressType == 'STREET') {

                result.street = [
                    address.AddressLine1 || '',
                    address.AddressLine2 || '',
                    address.AddressLine3 || '',
                    address.AddressLine4 || ''
                ].join(' ').trim();

                result.city = address.City || '';
                result.state = address.Region || '';
                result.postalCode = address.PostalCode || '';
                result.country = address.Country || '';

                break;
            }
        }

        return result;
    },

    getPhones: function(contact) {

        var result = {
            phone: '',
            fax: ''
        };

        if (!contact.Phones) {
            return result;
        }

        for (var i = 0; i < contact.Phones.length; i++) {

            var currentPhone = contact.Phones[i];

            var formattedPhone =
                (currentPhone.PhoneAreaCode || '') +
                (currentPhone.PhoneNumber || '');

            if (
                (currentPhone.PhoneType == 'DEFAULT' ||
                    currentPhone.PhoneType == 'MOBILE') &&
                !result.phone
            ) {

                result.phone = formattedPhone;
            }

            if (currentPhone.PhoneType == 'FAX') {

                result.fax = formattedPhone;
            }
        }

        return result;
    },

    updateCompany: function(
        company,
        contact,
        address,
        phones
    ) {

        if (phones.phone) {

            company.setValue(
                'phone',
                phones.phone
            );
        }

        if (phones.fax) {

            company.setValue(
                'fax_phone',
                phones.fax
            );
        }

        if (address.street) {

            company.setValue(
                'street',
                address.street
            );
        }

        if (address.city) {

            company.setValue(
                'city',
                address.city
            );
        }

        if (address.state) {

            company.setValue(
                'state',
                address.state
            );
        }

        if (address.postalCode) {

            company.setValue(
                'zip',
                address.postalCode
            );
        }

        if (address.country) {

            company.setValue(
                'country',
                address.country
            );
        }

        company.setValue(
            'customer',
            contact.IsCustomer
        );

        company.setValue(
            'x_snc_spm_xero_i_0_xero_contact_id',
            contact.ContactID
        );
    },

    createCompany: function(
        contact,
        address,
        phones
    ) {

        var company =
            new GlideRecord('customer_account');

        company.initialize();

        company.setValue(
            'name',
            contact.Name
        );

        this.updateCompany(
            company,
            contact,
            address,
            phones
        );

        return company.insert();
    },

    /**
     * Resend failed days UI action (time_card): shows the button only when
     * the user can read and write the time card and it has days in Error
     * in the Xero Time Entry Sync.
     */
    canResendFailedDays: function(timeCard) {
        if (!timeCard.canRead() || !timeCard.canWrite()) {
            return false;
        }
        var gr = new GlideRecord('x_snc_spm_xero_i_0_xero_time_entry_sync');
        gr.addQuery('time_card', timeCard.getUniqueValue());
        gr.addQuery('status', 'error');
        gr.setLimit(1);
        gr.query();
        return gr.hasNext();
    },

    /**
     * Retry Xero user match UI action (External User Mapping): shows the
     * button only when the user can read the record and it is a Xero
     * mapping still Not found.
     */
    canRetryUserMatch: function(mapping) {
        if (!mapping.canRead()) {
            return false;
        }
        return mapping.tool + '' == 'xero' && mapping.status + '' == 'not_found';
    },
    // ------------------------------------------------------------------
    // On-demand sync page (UI Page x_snc_spm_xero_i_0_xero_sync.do).
    // The page calls startOnDemandSync, getOnDemandSyncState and
    // getOnDemandProjects through the GlideAjax Script Include
    // XeroOnDemandSyncAjax.
    // Lock and last result come from sys_flow_context (platform record of
    // every execution), so nothing is stored by this feature.
    // ------------------------------------------------------------------
    ONDEMAND_ROLE: 'it_project_manager',
    ONDEMAND_PROJECT_SUBFLOW: 'x_snc_spm_xero_i_0.xero__createupdate_project',
    ONDEMAND_TASKS_SUBFLOW: 'x_snc_spm_xero_i_0.xero__sync_project_tasks',
    ONDEMAND_WEEKLY_FLOW: 'x_snc_spm_xero_i_0.xero__createupdate_projecttask_daily',
    ONDEMAND_RUNNING_STATES: 'QUEUED,IN_PROGRESS,WAITING,CONTINUE_SYNC,PAUSED',

    /**
     * Starts an on-demand sync in background.
     * action: 'update_tasks' (needs projectSysId), 'fetch_new' or 'sync_all'.
     * Returns { ok: true, contextId } or { ok: false, error }.
     */
    startOnDemandSync: function(action, projectSysId) {
        if (!gs.hasRole(this.ONDEMAND_ROLE)) {
            return {
                ok: false,
                error: 'not_authorized'
            };
        }
        if (action != 'update_tasks' && action != 'fetch_new' && action != 'sync_all') {
            return {
                ok: false,
                error: 'invalid_action'
            };
        }
        if (this._getOnDemandRunning()) {
            return {
                ok: false,
                error: 'running'
            };
        }

        var subflowName = this.ONDEMAND_PROJECT_SUBFLOW;
        var inputs = {};
        if (action == 'update_tasks') {
            var project = new GlideRecord('pm_project');
            if (!projectSysId || !project.get(projectSysId)) {
                return {
                    ok: false,
                    error: 'project_not_found'
                };
            }
            subflowName = this.ONDEMAND_TASKS_SUBFLOW;
            // FlowAPI Reference input needs the GlideRecord, not the sys_id string.
            inputs.project = project;
        } else {
            inputs.only_new = (action == 'fetch_new');
        }

        try {
            var result = sn_fd.FlowAPI.getRunner()
                .subflow(subflowName)
                .inBackground()
                .withInputs(inputs)
                .run();
            return {
                ok: true,
                contextId: result.getContextId()
            };
        } catch (ex) {
            gs.error('XeroIntegrationUtils.startOnDemandSync (' + action + '): ' + ex);
            return {
                ok: false,
                error: 'start_failed'
            };
        }
    },

    /**
     * State for the on-demand sync page.
     * running: any Weekly / Create-Update Project / Sync Project Tasks execution not finished.
     * last: most recent Create-Update Project or Sync Project Tasks execution, with totals.
     */
    getOnDemandSyncState: function() {
        if (!gs.hasRole(this.ONDEMAND_ROLE)) {
            return {
                ok: false,
                error: 'not_authorized'
            };
        }

        var state = {
            ok: true,
            running: this._getOnDemandRunning(),
            last: null
        };

        var tasksFlowId = this._getOnDemandFlowIds([this.ONDEMAND_TASKS_SUBFLOW]);
        var ctx = new GlideRecord('sys_flow_context');
        ctx.addQuery('flow', 'IN',
            this._getOnDemandFlowIds([this.ONDEMAND_PROJECT_SUBFLOW, this.ONDEMAND_TASKS_SUBFLOW]));
        ctx.orderByDesc('sys_created_on');
        ctx.setLimit(1);
        ctx.query();
        if (!ctx.next()) {
            return state;
        }

        var isTasks = ctx.getValue('flow') == tasksFlowId;
        var last = {
            contextId: ctx.getUniqueValue(),
            type: isTasks ? 'tasks' : 'projects',
            state: ctx.getValue('state'),
            startedAt: ctx.getDisplayValue('sys_created_on'),
            projectsCreated: 0,
            tasksCreated: 0,
            errors: 0
        };

        if (last.state == 'COMPLETE') {
            try {
                var out = sn_fd.FlowAPI.getOutputs(last.contextId) || {};
                last.tasksCreated = parseInt(out.tasks_created, 10) || 0;
                if (!isTasks) {
                    last.projectsCreated = parseInt(out.projects_created, 10) || 0;
                    last.errors = parseInt(out.errors, 10) || 0;
                }
            } catch (ex) {
                gs.warn('XeroIntegrationUtils.getOnDemandSyncState outputs (' + last.contextId + '): ' + ex);
            }
        }

        state.last = last;
        return state;
    },

    /**
     * Projects listed on the on-demand sync page: came from Xero (correlation_id),
     * company = property us_company, active. No call to Xero.
     */
    getOnDemandProjects: function() {
        if (!gs.hasRole(this.ONDEMAND_ROLE)) {
            return {
                ok: false,
                error: 'not_authorized'
            };
        }
        var list = [];
        var gr = new GlideRecord('pm_project');
        gr.addNotNullQuery('correlation_id');
        gr.addQuery('company', gs.getProperty('x_snc_spm_xero_i_0.us_company'));
        gr.addActiveQuery();
        gr.orderBy('short_description');
        gr.query();
        while (gr.next()) {
            list.push({
                id: gr.getUniqueValue(),
                number: gr.getValue('number'),
                name: gr.getValue('short_description')
            });
        }
        return {
            ok: true,
            projects: list
        };
    },

    _getOnDemandRunning: function() {
        var ctx = new GlideRecord('sys_flow_context');
        ctx.addQuery('flow', 'IN', this._getOnDemandFlowIds(
            [this.ONDEMAND_PROJECT_SUBFLOW, this.ONDEMAND_TASKS_SUBFLOW, this.ONDEMAND_WEEKLY_FLOW]));
        ctx.addQuery('state', 'IN', this.ONDEMAND_RUNNING_STATES);
        ctx.setLimit(1);
        ctx.query();
        return ctx.hasNext();
    },

    // sys_flow_context.flow holds the sys_hub_flow sys_id (string field):
    // resolve it at run time from the scoped names, no fixed sys_id.
    _getOnDemandFlowIds: function(scopedNames) {
        var ids = [];
        var flow = new GlideRecord('sys_hub_flow');
        flow.addQuery('sys_scope.scope', 'x_snc_spm_xero_i_0');
        flow.addQuery('internal_name', 'IN', scopedNames.map(function(n) {
            return n.split('.')[1];
        }).join(','));
        flow.query();
        while (flow.next()) {
            ids.push(flow.getUniqueValue());
        }
        return ids.join(',');
    },

    type: 'XeroIntegrationUtils'
};
